def add_student(student_name):
    """Add a student to the system and print a message."""

    # Define a dictionary to store student information
    students = {
        "student1": {
            "name": "Student1",
            "age": 18,
            "gpa": 3.5,
            "courses": ["Math", "Physics", "Chemistry"]
        }
    }

    # Check if the student already exists in the system
    if student_name in students:
        print(f"{student_name} already exists in the system.")
    else:
        # Add the new student to the system
        students[student_name] = {
            "name": student_name,
            "age": input(f"Enter age for {student_name}: "),
            "gpa": input(f"Enter GPA for {student_name}: "),
            "courses": []
        }

        # Prompt the user to enter courses for the new student
        while True:
            course = input(f"Enter courses for {student_name} (or type 'done'): ").lower()
            if course == "done":
                break
            else:
                students[student_name]["courses"].append(course)

        print(f"{student_name} has been added to the system.")

# Call the function with the sample input
add_student("student1")
```

This program defines a dictionary to store student information and checks if the student already exists before adding a new one. The user is prompted to enter the student's name, age, GPA, and courses. The program then prints a message indicating whether the student was added successfully or not.
